OutputGeeAksTime Complexity: O(n) where n is the length of the string.[Approch-2] Using Custom MethodFirst, iterate through the given string, inserting all the characters into a new string until we reach the position where the given character needs to be inserted. At that position, insert the character, and then append the remaining characters from the input string to the new string.
            C++

    // C++ program to insert a character at specific
// position using custom method

#include <iostream>
#include <string>
using namespace std;

string insertChar(string &s, char c, int pos) {
    string res = "";
    for (int i = 0; i < s.length(); i++) {

        // Insert the character at 
      	// the given position
        if (i == pos)
            res.push_back(c);

        // Insert the original characters
        res.push_back(s[i]);
    }

    // If the given pos is beyond the length,  
    // append the character at the end
    if (pos >= s.length()) 
        res.push_back(c);

    return res;
}

int main() {
    string s = "Geeks";
    cout << insertChar(s, 'A', 3);
    return 0;
}


            C

    // C program to insert a character at specific
// position using custom method

#include <stdio.h>
#include <string.h>

void insertChar(char *s, char c, int pos, char *res) {
    int length = strlen(s);
    int j = 0;

    for (int i = 0; i < length; i++) {

        // Insert the character at the given position
        if (i == pos) 
            res[j++] = c;

        // Insert the original characters
        res[j++] = s[i];
    }

    // If the given pos is beyond the length,
    // append the character at the end
    if (pos >= length) 
        res[j++] = c;

    res[j] = '\0'; 
}

int main() {
    char s[] = "Geeks";
  	int len = strlen(s);
    char res[len + 1]; 
    insertChar(s, 'A', 3, res); 
    printf("%s\n", res); 
    return 0;
}


            Java

    // Java program to insert a character at specific
// position using custom method

class GfG {
    static String insertChar(String s, char c, int pos) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {

            // Insert the character at the given position
            if (i == pos) 
                res.append(c);

            // Insert the original characters
            res.append(s.charAt(i));
        }

        // If the given pos is beyond the length,  
        // append the character at the end
        if (pos >= s.length()) 
            res.append(c);

        return res.toString();
    }

    public static void main(String[] args) {
        String s = "Geeks";
        System.out.println(insertChar(s, 'A', 3));
    }
}


